import{z as o,x as s,o as A,c as d,q as l,j as n,D as e,d as B,s as r,S as i,b as a}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"可解释性的深化","description":"","frontmatter":{"title":"可解释性的深化","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/fml-explainability-deep.md","filePath":"quant/fml-explainability-deep.md","lastUpdated":1791063341000}'),p={name:"quant/fml-explainability-deep.md"};function m(C,E,D,u,h,f){const t=s("Mermaid");return A(),d("div",null,[E[2]||(E[2]=l('<h1 id="可解释性的深化" tabindex="-1">可解释性的深化 <a class="header-anchor" href="#可解释性的深化" aria-label="Permalink to &quot;可解释性的深化&quot;">​</a></h1><div class="epigraph"><p>事后解释可以与被解释的模型不一致；高风险决策要的不是对黑箱的道歉，而是值得信任的结构。</p><footer>—— 据 Rudin, Nature Machine Intelligence, 2019 的立场整理</footer></div><p><a href="/quant/fml-ensembles">上一课</a>把预测方差摊平，代价是模型更像一只黑箱——投委会、风控与审计都要问「它在看什么」。<a href="/quant/shap-factor-attribution">SHAP 因子归因</a>立了 Shapley 会计的定义与干预型、条件型之别，<a href="/quant/mda-importance">MDA 特征重要性</a>立了置换口径与共线簇的坍缩。本课深化解释的工程与误读：全局与局部怎么分工、相关特征下各口径怎么读、解释怎么进验收与监控，以及解释自身的过拟合。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>解释有三类消费者，需求不同：投委会要「钱从哪个假设来」的全局叙事；风控要「这只票为什么被砍」的局部归因；审计要随版本稳定的特征与假设文档。错配因此成灾。拿局部的 Shapley 分摊拼全局故事——局部分摊不可加总成因果叙事；拿分裂增益说重要性——<a href="/quant/mda-importance">MDA</a> 已把它记在共线族最先被问到的那一列上；相关特征下单列归因在成员间任意转移，集成让这更糟：每个成员把同一份功劳记在不同的共线列上，平均之后看似稳定，实则谁也没说清。最静默的一类：解释被当监控探针用（哪列的归因突变），但探针自身没有基线，报警与噪声不可分。</p><p><span class="marginnote">Shapley 值翻译成大白话：把预测看成一桌人合点的菜钱，轮流问「少了他这份特征，分数会差多少」，再把所有加入顺序下的差额取平均——每人分到的份额就是他对这次预测的贡献。它回答「怎么分账」，不回答「谁导致谁」。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>分口径做四件事。全局：预指定特征族的 SHAP 和，与整簇置换的 MDA 并列双口径——共线簇整簇求和、整簇置换，簇内转移互相抵消后剩下的才是可辨识的量。局部：单笔归因配反事实——「把该列拨回截面中位数，分数变多少」，用数值回答「为什么砍仓」，而不是一段修辞。验证：解释对不对，用重训消融当近似真值——删整簇特征重训，折外变化应对齐簇级归因；对不齐的解释不上报告。文档：解释口径随模型哈希冻结，与<a href="/quant/fml-feature-store-deep">特征</a>和<a href="/quant/fml-model-selection-protocol">协议</a>同账，版本间的解释差异进变更记录。</p>',8)),(A(),n(i,null,{default:e(()=>[r(t,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20M%5B%22%E5%B7%B2%E9%AA%8C%E6%94%B6%E6%A8%A1%E5%9E%8B%EF%BC%88%E5%90%AB%E9%9B%86%E6%88%90%EF%BC%89%22%5D%20--%3E%20G%5B%22%E5%85%A8%E5%B1%80%EF%BC%9A%E7%89%B9%E5%BE%81%E6%97%8F%20SHAP%20%E5%92%8C%20%E5%8A%A0%20%E6%95%B4%E7%B0%87%20MDA%22%5D%0A%20%20M%20--%3E%20L%5B%22%E5%B1%80%E9%83%A8%EF%BC%9A%E5%8D%95%E7%AC%94%E5%BD%92%E5%9B%A0%20%E5%8A%A0%20%E5%8F%8D%E4%BA%8B%E5%AE%9E%22%5D%0A%20%20G%20--%3E%20V%5B%22%E9%AA%8C%E8%AF%81%EF%BC%9A%E9%87%8D%E8%AE%AD%E6%B6%88%E8%9E%8D%E5%AF%B9%E9%BD%90%E7%B0%87%E7%BA%A7%E5%BD%92%E5%9B%A0%22%5D%0A%20%20L%20--%3E%20V%0A%20%20V%20--%3E%7C%22'%E5%AF%B9%E4%B8%8D%E4%B8%8A%EF%BC%8C%E4%B8%8D%E4%B8%8A%E6%8A%A5%E5%91%8A'%22%7C%20FIX%5B%22%E4%BF%AE%E5%8F%A3%E5%BE%84%E6%88%96%E6%8D%A2%E7%BB%93%E6%9E%84%22%5D%0A%20%20V%20--%3E%7C%22'%E5%AF%B9%E4%B8%8A'%22%7C%20C1%5B%22%E6%8A%95%E5%A7%94%E4%BC%9A%EF%BC%9A%E5%85%A8%E5%B1%80%E5%8F%99%E4%BA%8B%22%5D%0A%20%20V%20--%3E%20C2%5B%22%E9%A3%8E%E6%8E%A7%EF%BC%9A%E5%B1%80%E9%83%A8%E5%BD%92%E5%9B%A0%22%5D%0A%20%20V%20--%3E%20C3%5B%22%E5%AE%A1%E8%AE%A1%EF%BC%9A%E5%86%BB%E7%BB%93%E6%96%87%E6%A1%A3%22%5D%0A"})]),fallback:e(()=>[...E[0]||(E[0]=[B(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("h2",{id:"机制",tabindex:"-1"},[B("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=a("p",null,"相关特征为什么让单列归因任意：共线族的预测贡献真实存在，但「功劳属于哪一列」没有唯一解——Shapley 定义在特征集合上，且依赖背景分布的取法；干预型与条件型在相关特征上可给出符号相反的归因，报告不写明口径，两份「都正确」的归因就会在同一个会上打架。簇级量为什么稳定：转移在簇内互相抵消，簇和与整簇置换的折外变化是几乎与分摊约定无关的量。解释的二次过拟合：用解释结果反过来挑特征、调模型，解释误差就进入选择环路——要么把这类尝试计入 \\(N\\) 台账，要么承诺「只读不改」；把 SHAP 排名直接当特征淘汰名单，是最常见的自欺，它等于用一份有偏估计做了第二轮选择。",-1)),E[5]||(E[5]=a("p",null,[a("span",{class:"marginnote"},"干预型与条件型的差别用数字说：若动量 5 日与 20 日相关 0.9，干预型把 20 日列「按住」不动、只拨动 5 日列，看分数变化；条件型允许 20 日列跟着联动。同一簇上两者可以给出符号相反的归因——报告不写明口径，两个都「对」的数字就会在会上打架。")],-1)),(A(),n(i,null,{default:e(()=>[r(t,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20LR%0A%20%20CLU%5B%22%E5%85%B1%E7%BA%BF%E7%B0%87%EF%BC%9A%E5%8A%A8%E9%87%8F%E6%97%8F%E4%B8%89%E5%88%97%E7%9B%B8%E5%85%B3%200.9%22%5D%20--%3E%20M1%5B%22%E6%88%90%E5%91%98%20A%20%E8%AE%B0%E5%8A%9F%E5%9C%A8%E5%88%97%201%22%5D%0A%20%20CLU%20--%3E%20M2%5B%22%E6%88%90%E5%91%98%20B%20%E8%AE%B0%E5%8A%9F%E5%9C%A8%E5%88%97%202%22%5D%0A%20%20CLU%20--%3E%20M3%5B%22%E6%88%90%E5%91%98%20C%20%E8%AE%B0%E5%8A%9F%E5%9C%A8%E5%88%97%203%22%5D%0A%20%20M1%20--%3E%20AVG%5B%22%E9%9B%86%E6%88%90%E5%B9%B3%E5%9D%87%E5%90%8E%E7%9A%84%E5%8D%95%E5%88%97%E5%BD%92%E5%9B%A0%22%5D%0A%20%20M2%20--%3E%20AVG%0A%20%20M3%20--%3E%20AVG%0A%20%20AVG%20--%3E%20Q%5B%22%E5%8D%95%E5%88%97%E8%AF%BB%E6%95%B0%EF%BC%9A%E7%9C%8B%E4%BC%BC%E7%A8%B3%E5%AE%9A%EF%BC%8C%E5%AE%9E%E5%88%99%E4%BB%BB%E6%84%8F%22%5D%0A%20%20CLU%20--%3E%20SUM%5B%22%E6%95%B4%E7%B0%87%E6%B1%82%E5%92%8C%E6%88%96%E6%95%B4%E7%B0%87%E7%BD%AE%E6%8D%A2%22%5D%0A%20%20SUM%20--%3E%20S%5B%22%E7%B0%87%E7%BA%A7%E9%87%8F%EF%BC%9A%E7%B0%87%E5%86%85%E8%BD%AC%E7%A7%BB%E6%8A%B5%E6%B6%88%EF%BC%8C%E7%A8%B3%E5%AE%9A%22%5D%0A"})]),fallback:e(()=>[...E[1]||(E[1]=[B(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=l('<p><span class="marginnote">用 SHAP 排名反挑特征，就像照着哈哈镜减肥：镜子（解释）本身是有偏估计，按它调整姿势（挑特征、调模型），下一张照片只会更歪——解释误差从此进入选择环路，回测成绩的改善分不清是真信号还是镜子的偏好。</span></p><p><span class="marginnote">监控探针要配基线：归因突变的报警阈值应在模型上线时按训练折的归因波动定带，而不是上线后看哪次「像」突变。探针没有基线，它的第一次报警就会消耗掉组织对它的信任。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>解释不是因果，也不是 PnL 归因——分数来源与收益来源之间隔着执行、成本与组合构建，中间每一环都能改写「哪列在赚钱」。它不替代<a href="/quant/sr-11-7-model-risk">SR 11-7</a> 的独立验证：有效挑战要独立复现，不能只读开发者自备的解释报告。白箱与黑箱是两条路线，本课不替你选：线性、浅树、单调约束 GBDT 一类内生可解释结构在弱信号世界里常常只损失可忽略的精度；选择的标准是——上了黑箱就要付解释工程的账，付不起就换白箱。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>三类消费者三种口径：全局叙事、局部归因、冻结文档，不可互相顶替。</li><li>相关特征下单列归因任意，报告用簇级量并写明干预型或条件型。</li><li>解释以重训消融验证，对不齐不上报告；探针要配上线时定带的基线。</li><li>用解释反挑特征是第二轮选择，计入 \\(N\\) 或只读不改。</li><li>出处：Lundberg and Lee, <em>NeurIPS</em>, 2017；Rudin, <em>Nature Machine Intelligence</em>, 2019；Breiman, <em>Machine Learning</em>, 2001。</li></ul>',6))])}const S=o(p,[["render",m]]);export{c as __pageData,S as default};
